import sys

def solve():
    s = sys.stdin.readline().strip()
    matching = {
        ')': '(',
        ']': '[',
        '>': '<'
    }

    stack = []

    for ch in s:
        if ch in matching:
            if not stack or stack[-1] != matching[ch]:
                print("No")
                return
            stack.pop()
        else:
            stack.append(ch)

    print("Yes" if not stack else "No")

if __name__ == "__main__":
    solve()
