import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    idx = 0
    n = data[idx]
    idx += 1

    dice = []
    for _ in range(n):
        k = data[idx]
        idx += 1
        cnt = {}
        for _ in range(k):
            a = data[idx]
            idx += 1
            cnt[a] = cnt.get(a, 0) + 1
        dice.append((k, cnt))

    # Iterate over the smaller dictionary for each pair.
    dice.sort(key=lambda x: len(x[1]))

    prepared = [(k, tuple(cnt.items()), cnt.get) for k, cnt in dice]

    best_num = 0
    best_den = 1

    for i in range(n - 1):
        ki, items_i, _ = prepared[i]
        for j in range(i + 1, n):
            kj, _, get_j = prepared[j]

            num = 0
            for val, c in items_i:
                c2 = get_j(val)
                if c2:
                    num += c * c2

            if num:
                den = ki * kj
                if num * best_den > best_num * den:
                    best_num = num
                    best_den = den

    print(f"{best_num / best_den:.15f}")


if __name__ == "__main__":
    main()

